package vn.iotstar.controller;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import vn.iotstar.dto.*;import vn.iotstar.service.*;@Controller public class AuthController{public AuthController(AuthService auth,OtpService otp){this.auth=auth;this.otp=otp;}final AuthService auth;final OtpService otp;@GetMapping("/login")public String login(){return "auth/login";}@GetMapping("/register")public String register(Model m){m.addAttribute("registerDTO",new RegisterDTO());return "auth/register";}@PostMapping("/register")public String register(@Valid @ModelAttribute RegisterDTO d,BindingResult r,RedirectAttributes a){if(r.hasErrors())return "auth/register";try{auth.register(d);a.addFlashAttribute("success","OTP đã được gửi đến email.");return "redirect:/verify-otp?email="+d.getEmail();}catch(IllegalArgumentException e){r.reject("register.error",e.getMessage());return "auth/register";}}@GetMapping("/verify-otp")public String verifyPage(@RequestParam(required=false)String email,Model m){VerifyOtpDTO d=new VerifyOtpDTO();d.setEmail(email);m.addAttribute("verifyOtpDTO",d);return "auth/verify-otp";}@PostMapping("/verify-otp")public String verify(@Valid @ModelAttribute VerifyOtpDTO d,BindingResult r,RedirectAttributes a){if(r.hasErrors())return "auth/verify-otp";if(!auth.verifyRegister(d.getEmail(),d.getOtp())){r.reject("otp.error","OTP không hợp lệ, hết hạn hoặc đã quá số lần thử.");return "auth/verify-otp";}a.addFlashAttribute("success","Xác nhận thành công. Hãy đăng nhập.");return "redirect:/login";}@PostMapping("/resend-register-otp")public String resend(@RequestParam String email,RedirectAttributes a){otp.sendRegisterOtp(email);a.addFlashAttribute("success","Đã gửi lại OTP.");return "redirect:/verify-otp?email="+email;}@GetMapping("/forgot-password")public String forgot(Model m){m.addAttribute("forgotPasswordDTO",new ForgotPasswordDTO());return "auth/forgot-password";}@PostMapping("/forgot-password")public String forgot(@Valid @ModelAttribute ForgotPasswordDTO d,BindingResult r,RedirectAttributes a){if(r.hasErrors())return "auth/forgot-password";try{auth.forgotPassword(d.getEmail());a.addFlashAttribute("email",d.getEmail());return "redirect:/reset-password";}catch(IllegalArgumentException e){r.reject("forgot.error",e.getMessage());return "auth/forgot-password";}}@GetMapping("/reset-password")public String reset(Model m){ResetPasswordDTO d=new ResetPasswordDTO();Object e=m.asMap().get("email");if(e!=null)d.setEmail(e.toString());m.addAttribute("resetPasswordDTO",d);return "auth/reset-password";}@PostMapping("/reset-password")public String reset(@Valid @ModelAttribute ResetPasswordDTO d,BindingResult r,@RequestParam String otp,RedirectAttributes a){if(!d.getPassword().equals(d.getConfirmPassword()))r.reject("password.error","Mật khẩu xác nhận không đúng.");if(r.hasErrors())return "auth/reset-password";if(!auth.verifyResetOtp(d.getEmail(),otp)){r.reject("otp.error","OTP không hợp lệ hoặc đã hết hạn.");return "auth/reset-password";}auth.resetPassword(d.getEmail(),d.getPassword());a.addFlashAttribute("success","Đổi mật khẩu thành công.");return "redirect:/login";}}
